INSERT INTO remedies (id, name, condition, condition_label, description, instructions, timing, tracking_note, evidence, caution, premium) VALUES
('warm_sitz_bath_hemorrhoids', 'Warm Sitz Baths', 'hemorrhoids', 'Hemorrhoid Discomfort (Piles)', 'Warm water relaxes the muscles around the anus and eases swelling, itching and soreness.', 'Sit in a few inches of warm (not hot) water for 10-15 minutes, then pat the area dry gently.', '2-3 times daily, especially after bowel movements.', 'Rate discomfort before and after each bath.', 'Sitz baths are a standard first-line comfort measure for hemorrhoids.', NULL, false),
('fibre_water_hemorrhoids', 'Fibre-Rich Foods and Plenty of Water', 'hemorrhoids', 'Hemorrhoid Discomfort (Piles)', 'Soft, easy-to-pass stools mean less straining, which is the main thing that aggravates piles.', 'Add beans, oats, vegetables and fruit with the skin on to your meals, and drink water steadily through the day.', 'Daily, ongoing.', 'Note stool softness and discomfort over a couple of weeks.', 'Dietary fibre and fluids are the cornerstone of managing hemorrhoids.', 'Bleeding that is heavy, keeps happening, or comes with pain needs a doctor - never assume rectal bleeding is just piles.', true),
('no_straining_hemorrhoids', 'Do Not Strain or Linger on the Toilet', 'hemorrhoids', 'Hemorrhoid Discomfort (Piles)', 'Straining and long toilet sits increase pressure on the veins around the anus.', 'Go when you feel the urge, keep toilet time short and phone-free, and raise your knees on a small footstool.', 'Every bathroom visit.', 'Track how often you strain and how sore you feel.', 'Reducing straining is widely recommended to ease and prevent flare-ups.', 'A lump that is very painful or does not settle within a week should be seen by a doctor.', true),
('warm_salt_gargle_throat', 'Warm Salt Water Gargle', 'sore_throat', 'Sore Throat', 'Salt water draws fluid out of swollen throat tissue and helps loosen mucus.', 'Stir a good pinch of salt into a glass of warm water, gargle for 20-30 seconds, then spit it out.', '3-4 times daily while sore.', 'Rate throat pain morning and evening.', 'Salt water gargling is a long-standing, commonly recommended comfort measure.', NULL, false),
('honey_warm_drink_throat', 'Warm Drink With Honey and Lemon', 'sore_throat', 'Sore Throat', 'Warm liquids soothe irritated tissue and honey coats the throat.', 'Stir a spoonful of honey and a squeeze of lemon into warm (not scalding) water or herbal tea and sip slowly.', 'Several times daily, especially before bed.', 'Note how your throat feels after each drink.', 'Honey has soothing properties and is commonly used for throat irritation.', 'Never give honey to babies under 1 year old.', true),
('rest_voice_fluids_throat', 'Rest Your Voice and Keep Fluids Up', 'sore_throat', 'Sore Throat', 'A dry, strained throat heals slower; rest and moisture help the tissue recover.', 'Talk less, avoid whispering or shouting, and sip water or warm fluids regularly.', 'Through the day until it settles.', 'Track pain and how many days it lasts.', 'Voice rest and hydration are standard supportive care for sore throats.', 'See a doctor if the pain is severe, lasts over a week, or comes with trouble swallowing, trouble breathing or a high fever.', true),
('honey_water_cough', 'Honey in Warm Water', 'cough', 'Cough', 'Honey coats the throat and can calm the tickle that triggers coughing.', 'Stir a spoonful of honey into warm water or herbal tea and sip slowly, especially in the evening.', '1-3 times daily, and before bed.', 'Note how often you cough at night.', 'Honey is a well-studied, commonly recommended soother for coughs.', 'Never give honey to babies under 1 year old.', false),
('steam_cough', 'Steam From a Warm Shower', 'cough', 'Cough', 'Moist air loosens mucus and soothes an irritated airway.', 'Sit in a steamy bathroom or breathe in the steam from a warm shower for 10 minutes.', '1-2 times daily.', 'Track how your chest and throat feel afterwards.', 'Humidified air is a standard supportive measure for cough and congestion.', 'Keep a safe distance from very hot water to avoid scalds.', true),
('head_up_hydrate_cough', 'Prop Your Head Up and Stay Hydrated', 'cough', 'Cough', 'Lying flat lets mucus drip down the throat and trigger coughing; fluids keep mucus thin.', 'Add an extra pillow at night and drink water or warm fluids regularly through the day.', 'Nightly, plus fluids through the day.', 'Log night-time coughing for a few days.', 'Elevation and hydration are common supportive steps for nighttime coughs.', 'A cough lasting more than 3 weeks, or with blood, chest pain or shortness of breath, needs a doctor.', true),
('steam_stuffy_nose', 'Steam Inhalation', 'stuffy_nose', 'Blocked / Stuffy Nose', 'Warm moist air thins mucus and helps the nasal passages drain.', 'Breathe in the steam from a warm shower or a bowl of hot water (with a towel over your head if you like) for 5-10 minutes.', '1-3 times daily.', 'Rate how open your nose feels before and after.', 'Steam is a widely used way to ease nasal congestion for short-term relief.', 'Keep your face a safe distance from hot water to avoid scalds.', false),
('saline_rinse_stuffy_nose', 'Saline Nasal Rinse', 'stuffy_nose', 'Blocked / Stuffy Nose', 'A salt water rinse flushes out mucus and irritants and reduces swelling inside the nose.', 'Use a saline spray or a neti pot with salt water once or twice a day.', '1-2 times daily.', 'Track congestion levels across a few days.', 'Nasal saline irrigation is well supported for relieving congestion.', 'Use distilled or boiled-and-cooled water only, never straight tap water.', true),
('warm_compress_stuffy_nose', 'Warm Compress and Head-Up Sleep', 'stuffy_nose', 'Blocked / Stuffy Nose', 'Gentle warmth over the nose and cheeks eases pressure, and sleeping propped up helps drainage.', 'Hold a warm damp cloth over your nose and cheeks for a few minutes, and add an extra pillow at night.', 'Daily, and at bedtime.', 'Note how well you can breathe at night.', 'Warmth and elevation are common comfort measures for blocked noses.', 'Congestion lasting more than 10 days, or with high fever or severe facial pain, should be checked by a doctor.', true),
('warm_compress_sinus', 'Warm Compress Over the Sinuses', 'sinus_pressure', 'Sinus Pressure', 'Warmth eases the pressure and aching around the cheeks, nose and forehead.', 'Rest a warm damp cloth over your cheeks, nose and forehead for 5-10 minutes.', '2-3 times daily.', 'Rate facial pressure before and after.', 'Warm compresses are a commonly recommended comfort measure for sinus pressure.', NULL, false),
('hydrate_humidify_sinus', 'Drink Fluids and Add Moisture to the Air', 'sinus_pressure', 'Sinus Pressure', 'Thin mucus drains more easily, which relieves the build-up behind the face.', 'Drink water and warm fluids through the day, and use a humidifier or steamy shower in dry rooms.', 'Daily until it eases.', 'Track pressure levels alongside fluid intake.', 'Hydration and humidified air are standard supportive measures for sinus symptoms.', NULL, true),
('gentle_massage_sinus', 'Gentle Sinus-Area Massage', 'sinus_pressure', 'Sinus Pressure', 'Light pressure may help encourage drainage and ease the tight, full feeling.', 'Use your fingertips to make slow, gentle circles on your cheekbones, beside the nose and on your brow for a minute or two.', '1-2 times daily.', 'Note whether the pressure eases afterwards.', 'Gentle facial massage is commonly suggested for temporary sinus comfort.', 'Facial pain with fever, or symptoms lasting more than 10 days, need a doctor.', true),
('cool_compress_sunburn', 'Cool Compresses and Cool Showers', 'sunburn', 'Sunburn', 'Cooling pulls heat out of the skin and calms the burning, stinging feeling.', 'Apply a cool damp cloth to the burn for 10-15 minutes, or take a cool shower, then pat dry gently.', 'Several times daily for the first couple of days.', 'Rate pain and redness each day.', 'Cooling the skin is a standard first step for sunburn relief.', 'Never put ice directly on the skin.', false),
('aloe_sunburn', 'Aloe Vera Gel', 'sunburn', 'Sunburn', 'Aloe vera is cooling and moisturizing and helps soothe sun-damaged skin.', 'Smooth a thin layer of pure aloe vera gel over the cooled skin.', '2-3 times daily while skin is tender.', 'Track redness and peeling over several days.', 'Aloe vera is widely used for soothing mild sunburn.', NULL, true),
('hydrate_shade_sunburn', 'Drink Water and Stay Out of the Sun', 'sunburn', 'Sunburn', 'Sunburn pulls fluid to the skin''s surface and more sun just adds more damage.', 'Drink extra water, wear loose soft clothing over the area, and stay in the shade until it heals.', 'Until the skin has healed.', 'Note how the skin looks each day.', 'Hydration and avoiding further exposure are standard sunburn advice.', 'Blistering over a large area, fever, chills, confusion or dizziness need medical care.', true),
('cold_compress_bites', 'Cold Compress', 'insect_bites', 'Insect Bites', 'Cold numbs the area and reduces swelling and itching.', 'Hold a cold damp cloth or wrapped ice pack on the bite for 10 minutes.', 'As needed, a few times daily.', 'Rate itch and swelling at the start and a few hours later.', 'Cold compresses are a standard first step for insect bites.', 'Never put ice directly on the skin.', false),
('no_scratch_bites', 'Resist Scratching and Keep It Clean', 'insect_bites', 'Insect Bites', 'Scratching breaks the skin, which lets germs in and makes bites itch for longer.', 'Wash the bite gently with soap and water, keep nails short, and cover it if you cannot stop scratching.', 'Daily until healed.', 'Check the bite each day for changes.', 'Avoiding scratching lowers the chance of a skin infection.', NULL, true),
('oatmeal_soothe_bites', 'Soothing Oatmeal Bath or Paste', 'insect_bites', 'Insect Bites', 'Oatmeal calms irritated, itchy skin.', 'Soak in a lukewarm bath with finely ground oats, or mix ground oats with a little water into a paste and leave it on the bite for 10 minutes.', 'Once or twice daily if very itchy.', 'Rate itch before and after.', 'Colloidal oatmeal is a well-known skin soother for itchy conditions.', 'Spreading redness, swelling of the face or lips, or trouble breathing needs urgent medical care.', true),
('cool_water_burns', 'Cool Running Water Straight Away', 'minor_burns', 'Minor Burns', 'Cooling stops the burn going deeper and eases pain.', 'Hold the burn under cool (not icy) running water for 10-20 minutes. Do not use butter, toothpaste or ice.', 'Immediately after the burn.', 'Note the size and colour of the burn.', 'Cool running water is the standard first aid for minor burns.', 'Burns larger than your palm, or on the face, hands, feet or genitals, or any deep or blistering burn, need medical care.', false),
('cover_clean_burns', 'Cover Loosely With a Clean Dressing', 'minor_burns', 'Minor Burns', 'A clean covering protects tender skin from germs and friction.', 'After cooling, cover the burn loosely with a clean non-stick dressing or cling film and keep it clean and dry.', 'Change daily or if it gets wet.', 'Check for redness, swelling or pus each day.', 'Covering minor burns protects against infection and eases pain.', NULL, true),
('leave_blisters_burns', 'Leave Blisters Alone', 'minor_burns', 'Minor Burns', 'A blister is the body''s natural protective cover over healing skin.', 'Do not pop blisters. Once healed, moisturize gently with aloe or a plain moisturizer.', 'Until fully healed.', 'Track healing over a week or two.', 'Leaving blisters intact lowers infection risk and supports healing.', 'Signs of infection like spreading redness, pus or fever need a doctor.', true),
('pressure_rinse_cuts', 'Press to Stop Bleeding, Then Rinse Clean', 'minor_cuts_scrapes', 'Minor Cuts and Scrapes', 'Firm pressure stops the bleeding, and rinsing removes dirt that could cause infection.', 'Press a clean cloth on the cut for a few minutes, then rinse gently under clean running water and pat dry.', 'Straight after the injury.', 'Note how long the bleeding takes to stop.', 'Pressure and rinsing are the standard first aid steps for minor wounds.', 'Deep cuts, bleeding that will not stop after 10 minutes, or dirt that will not rinse out need medical care.', false),
('keep_covered_cuts', 'Keep It Covered and Slightly Moist', 'minor_cuts_scrapes', 'Minor Cuts and Scrapes', 'Covered wounds heal faster and with less scarring than dry, exposed ones.', 'Cover the cut with a clean plaster or dressing and change it daily or when it gets wet or dirty.', 'Daily until healed.', 'Photograph the wound every couple of days to track healing.', 'Moist, covered wound healing is standard guidance for minor injuries.', NULL, true),
('watch_signs_cuts', 'Check Daily for Signs of Infection', 'minor_cuts_scrapes', 'Minor Cuts and Scrapes', 'Catching infection early keeps a small wound from becoming a bigger problem.', 'Look at the wound each day for spreading redness, warmth, swelling, pus or increasing pain.', 'Daily until healed.', 'Note any changes in redness or swelling.', 'Monitoring for infection signs is standard wound-care advice.', 'See a doctor if you notice signs of infection, or if you are unsure when you last had a tetanus booster.', true),
('rehydrate_hangover', 'Rehydrate Steadily', 'hangover', 'Hangover', 'Alcohol dries the body out, and low fluids add to the headache and tiredness.', 'Sip water, coconut water or clear broth steadily through the day instead of gulping.', 'Through the day.', 'Note headache and tiredness as you rehydrate.', 'Rehydration is the core supportive step for a hangover.', NULL, false),
('bland_food_hangover', 'Eat Bland, Easy Food', 'hangover', 'Hangover', 'Low blood sugar and an irritated stomach make simple food easier to keep down.', 'Try toast, bananas, rice, eggs or soup in small amounts until your stomach settles.', 'Small meals through the day.', 'Track nausea and energy levels.', 'Bland, easily digested foods are commonly recommended for hangover nausea.', NULL, true),
('rest_gentle_hangover', 'Rest and Go Easy on Yourself', 'hangover', 'Hangover', 'Sleep quality takes a hit after drinking, so your body needs time to recover.', 'Rest, take a short walk for fresh air if you feel up to it, and avoid more alcohol.', 'That day.', 'Note how many hours it takes to feel normal again.', 'Rest and time are the only reliable hangover recovery.', 'Repeated vomiting, confusion, seizures or extreme drowsiness after heavy drinking need urgent medical care.', true),
('salt_rinse_toothache', 'Warm Salt Water Rinse', 'toothache', 'Toothache', 'Salt water gently cleans the area and can calm irritated gum tissue.', 'Swish warm salt water around your mouth for 30 seconds, then spit it out.', '2-3 times daily.', 'Rate the pain before and after rinsing.', 'Salt water rinses are a common temporary comfort measure for toothache.', 'This only eases symptoms - a toothache needs a dentist visit.', false),
('cold_compress_toothache', 'Cold Compress on the Cheek', 'toothache', 'Toothache', 'Cold reduces swelling and dulls the ache.', 'Hold a cold pack wrapped in a cloth against your cheek over the sore tooth for 15 minutes.', 'A few times daily.', 'Note any swelling and pain levels.', 'Cold compresses are commonly suggested for dental pain and swelling.', 'Never put ice directly on the skin.', true),
('avoid_triggers_toothache', 'Avoid Triggers and Keep Cleaning Gently', 'toothache', 'Toothache', 'Very hot, cold or sugary foods and hard chewing can set off sharp pain in a sore tooth.', 'Chew on the other side, skip extremes of temperature and sweet foods, and keep brushing gently around the tooth.', 'Until you see a dentist.', 'Note which foods trigger the pain.', 'Avoiding triggers reduces irritation while you wait for dental care.', 'Facial swelling, fever, or trouble swallowing or breathing with a toothache is urgent.', true),
('warm_compress_earache', 'Warm Compress Over the Ear', 'earache', 'Earache', 'Gentle warmth eases the aching and relaxes tight muscles around the ear.', 'Hold a warm (not hot) damp cloth or a warm water bottle wrapped in a towel against the ear for 10-15 minutes.', 'A few times daily.', 'Rate the pain before and after.', 'Warm compresses are a common home comfort measure for ear pain.', NULL, false),
('rest_upright_earache', 'Rest With Your Head Raised', 'earache', 'Earache', 'Lying flat can increase pressure in the ear, while sitting up helps drainage.', 'Rest propped on extra pillows and sleep with the sore ear facing up.', 'At night and while resting.', 'Note how the pain feels in the morning.', 'Elevating the head is a common comfort tip for ear pain.', NULL, true),
('keep_dry_earache', 'Keep the Ear Dry and Do Not Poke Anything In', 'earache', 'Earache', 'Moisture and poking can irritate the ear canal or push germs further in.', 'Keep water out while showering and never use cotton buds or objects inside the ear.', 'Until the pain is gone.', 'Note any new discharge or changes in hearing.', 'Protecting the ear canal is standard advice when the ear is painful.', 'Ear pain with fever, discharge, hearing loss, or lasting more than 2 days needs a doctor, especially in children.', true),
('hourly_reset_posture', 'Hourly Posture Reset', 'poor_posture', 'Poor Posture / Slouching', 'Slumping builds up gradually, and regular resets stop muscles from locking into a poor position.', 'Set a reminder every hour: sit tall, drop your shoulders back and down, tuck your chin slightly and stand up for a minute.', 'Hourly while sitting.', 'Note how your neck and shoulders feel by end of day.', 'Regular movement breaks are recommended to reduce strain from prolonged sitting.', NULL, false),
('desk_setup_posture', 'Adjust Your Screen and Chair Height', 'poor_posture', 'Poor Posture / Slouching', 'A poorly set up workspace pulls your head forward and rounds your back.', 'Raise your screen so the top is at eye level, keep feet flat and elbows at about 90 degrees.', 'Set up once, check weekly.', 'Track neck and back comfort across a week.', 'Ergonomic setup is a first-line recommendation for posture-related aches.', NULL, true),
('chest_opener_posture', 'Doorway Chest Stretch', 'poor_posture', 'Poor Posture / Slouching', 'Tight chest muscles pull the shoulders forward, and stretching them helps your shoulders sit back naturally.', 'Stand in a doorway with arms on the frame at shoulder height and gently lean forward until you feel a stretch. Hold for 30 seconds.', '1-2 times daily.', 'Notice shoulder position and tightness over a few weeks.', 'Chest stretching is commonly recommended for rounded shoulders.', 'Back or neck pain with numbness, tingling or weakness needs a doctor.', true),
('steady_sipping_dehydration', 'Sip Fluids Steadily All Day', 'dehydration', 'Mild Dehydration', 'Small regular sips are absorbed better than a large amount all at once.', 'Keep a water bottle within reach and take sips every 15-20 minutes, adding a little juice or a pinch of salt if you have been sweating a lot.', 'Through the day.', 'Note thirst, headache and energy levels.', 'Steady fluid intake is the standard approach to mild dehydration.', NULL, false),
('water_rich_foods_dehydration', 'Eat Water-Rich Foods', 'dehydration', 'Mild Dehydration', 'Many fruits and vegetables add fluid and minerals along with their nutrients.', 'Add cucumber, watermelon, oranges, tomatoes and soups to your meals.', 'Daily.', 'Track how often you feel thirsty or tired.', 'Water-rich foods contribute meaningfully to daily fluid intake.', NULL, true),
('urine_colour_dehydration', 'Use Urine Colour as a Guide', 'dehydration', 'Mild Dehydration', 'Pale straw-coloured urine is a simple sign you are drinking enough.', 'Check your urine colour a few times a day and drink more if it looks dark yellow.', 'Throughout the day.', 'Note colour trends alongside how you feel.', 'Urine colour is a widely used quick check of hydration.', 'Dizziness that does not ease, very little urine, confusion or a racing heartbeat need medical attention.', true),
('warm_oil_dry_hair', 'Warm Oil Treatment', 'dry_hair', 'Dry, Frizzy Hair', 'Natural oils seal moisture into the hair shaft and smooth the surface.', 'Warm a little coconut or olive oil, work it through the lengths and ends, leave for 30 minutes to an hour, then shampoo out.', 'Once a week.', 'Compare softness and frizz week to week.', 'Oils like coconut oil are widely used to reduce hair protein loss and dryness.', NULL, false),
('lukewarm_wash_dry_hair', 'Wash Less and Use Lukewarm Water', 'dry_hair', 'Dry, Frizzy Hair', 'Hot water and frequent shampooing strip away the scalp''s natural oils.', 'Wash only as often as needed, focus shampoo on the scalp, and rinse with lukewarm or cool water.', 'Ongoing.', 'Note dryness as you reduce wash frequency.', 'Gentler washing is commonly advised to protect dry hair.', NULL, true),
('gentle_styling_dry_hair', 'Cut Back on Heat and Style Gently', 'dry_hair', 'Dry, Frizzy Hair', 'Heat tools and rough towel drying damage the outer layer of the hair.', 'Air-dry when you can, blot with a soft towel or old t-shirt, and use a wide-toothed comb on damp hair.', 'Ongoing.', 'Track breakage and frizz over a month.', 'Reducing heat and friction is standard advice for damaged hair.', 'Sudden dryness with tiredness or hair thinning can point to a nutrition or thyroid issue worth checking.', true),
('gentle_exfoliate_dull_skin', 'Gentle Exfoliation Once or Twice a Week', 'dull_skin', 'Dull, Tired-Looking Skin', 'Dead cells build up on the surface and make skin look flat and lifeless.', 'Use a soft cloth or a mild exfoliating product on damp skin, with light circular motions, then moisturize.', 'Once or twice weekly.', 'Compare glow and texture over 3-4 weeks.', 'Gentle exfoliation is a standard way to improve skin radiance.', 'Stop if your skin stings, turns red or feels raw.', false),
('water_sleep_dull_skin', 'Water, Sleep and Colour on Your Plate', 'dull_skin', 'Dull, Tired-Looking Skin', 'Skin reflects hydration, rest and nutrition, and dullness often appears when those slip.', 'Aim for steady water intake, consistent sleep, and fruit and vegetables of different colours daily.', 'Daily, ongoing.', 'Note your skin''s glow alongside sleep and diet.', 'Hydration, sleep and a varied diet are consistently linked to healthier-looking skin.', NULL, true),
('daily_sunscreen_dull_skin', 'Daily Sun Protection', 'dull_skin', 'Dull, Tired-Looking Skin', 'Sun exposure steadily dulls skin and darkens uneven patches.', 'Apply sunscreen to your face and neck every morning, even on cloudy days.', 'Every morning.', 'Take a photo monthly to compare tone.', 'Daily sunscreen is the most consistently recommended step for skin health.', NULL, true),
('gentle_cleanse_pores', 'Cleanse Gently Twice a Day', 'clogged_pores', 'Clogged Pores / Blackheads', 'Oil and dead skin settle into pores, and regular gentle cleansing stops them building up.', 'Wash your face morning and night with a mild cleanser and lukewarm water, then pat dry.', 'Morning and evening.', 'Compare blackheads and texture over 3-4 weeks.', 'Regular gentle cleansing is a first-line step for congested pores.', 'Avoid harsh scrubbing, which can irritate skin and make pores look worse.', false),
('warm_steam_pores', 'Warm Steam Before Cleansing', 'clogged_pores', 'Clogged Pores / Blackheads', 'Warmth softens the oil in pores so it is easier to cleanse away.', 'Hold your face over a bowl of warm (not boiling) water for a few minutes, or press a warm cloth on your face, then cleanse gently.', 'Once a week.', 'Note how your skin feels afterwards.', 'Warm steam is commonly used to loosen oil before cleansing.', 'Never squeeze or pick at blackheads - it can cause scarring.', true),
('clay_mask_pores', 'Weekly Clay Mask', 'clogged_pores', 'Clogged Pores / Blackheads', 'Clay absorbs excess oil and helps lift debris from pores.', 'Apply a thin layer of clay mask to oily areas, leave until just dry, then rinse off and moisturize.', 'Once a week.', 'Track oiliness and pore appearance.', 'Clay is commonly used to absorb excess oil from congested skin.', NULL, true),
('sunscreen_acne_scars', 'Protect Marks From the Sun Every Day', 'acne_scars', 'Acne Marks and Scars', 'Sun exposure darkens post-acne marks and makes them last longer.', 'Apply sunscreen to your face every morning, especially over areas with marks.', 'Every morning.', 'Take a monthly photo to track how marks are fading.', 'Sun protection is consistently recommended to help post-acne marks fade.', NULL, false),
('stop_picking_acne_scars', 'Stop Picking at Spots', 'acne_scars', 'Acne Marks and Scars', 'Picking damages the deeper layers of skin, which is what causes lasting marks and scars.', 'Leave spots alone, and cover them with a pimple patch if you tend to touch them.', 'Ongoing.', 'Note how many new marks appear each month.', 'Picking is a leading cause of post-acne scarring.', NULL, true),
('brighten_gently_acne_scars', 'Gentle Brightening and Patience', 'acne_scars', 'Acne Marks and Scars', 'Marks fade slowly as skin renews itself, and gentle products can support that.', 'Use a gentle brightening product, such as one with vitamin C or niacinamide, and give it at least 8-12 weeks.', 'Daily, ongoing.', 'Compare photos every month.', 'Post-acne marks usually fade over months with sun protection and consistency.', 'Deep, pitted, painful or raised scars are worth seeing a dermatologist about.', true),
('gentle_movement_sore_muscles', 'Keep Moving Gently', 'sore_muscles', 'Sore Muscles After Exercise', 'Light activity increases blood flow to tight muscles and helps stiffness ease sooner.', 'Go for a walk, stretch lightly or do easy yoga instead of staying completely still.', 'Daily while sore.', 'Rate soreness each morning.', 'Light movement is commonly recommended for post-exercise soreness.', NULL, false),
('warm_bath_sore_muscles', 'Warm Bath or Heat Pack', 'sore_muscles', 'Sore Muscles After Exercise', 'Warmth relaxes tight muscles and eases the aching.', 'Soak in a warm bath for 15-20 minutes, or rest a warm pack on the sore area.', 'Once daily as needed.', 'Note soreness before and after.', 'Heat therapy is a common comfort measure for muscle soreness.', NULL, true),
('fuel_rest_sore_muscles', 'Eat Protein, Drink Water and Sleep', 'sore_muscles', 'Sore Muscles After Exercise', 'Muscles repair during rest, and they need protein and fluid to rebuild.', 'Include protein foods like eggs, beans, fish or yoghurt, drink enough water and get a full night of sleep.', 'Daily, especially after workouts.', 'Note how quickly soreness fades.', 'Protein, hydration and sleep all support muscle recovery.', 'Severe pain, marked swelling, dark urine, or soreness that does not ease after a few days need medical attention.', true),
('sip_water_dry_mouth', 'Sip Water Regularly', 'dry_mouth', 'Dry Mouth', 'Frequent sips keep the mouth moist and help protect teeth and gums.', 'Keep water with you and take small sips throughout the day, especially at night and during meals.', 'Through the day.', 'Rate dryness morning and evening.', 'Regular fluids are the simplest first step for dry mouth.', NULL, false),
('gum_ice_dry_mouth', 'Chew Sugar-Free Gum or Suck on Ice Chips', 'dry_mouth', 'Dry Mouth', 'Chewing and sucking stimulate your glands to make more saliva.', 'Chew sugar-free gum or let small ice chips melt in your mouth when your mouth feels dry.', 'As needed.', 'Note how long relief lasts.', 'Saliva stimulation is a standard approach to dry mouth.', NULL, true),
('nose_breathe_humidify_dry_mouth', 'Breathe Through Your Nose and Humidify at Night', 'dry_mouth', 'Dry Mouth', 'Mouth breathing and dry air dry out the mouth, especially overnight.', 'Use a humidifier in the bedroom and cut back on caffeine, alcohol and tobacco in the evening.', 'Nightly.', 'Compare how your mouth feels in the morning.', 'Humidified air and avoiding drying substances are commonly advised.', 'Dry mouth lasting weeks, or with extreme thirst or frequent urination, should be checked by a doctor.', true),
('consistent_schedule_night_waking', 'Keep a Consistent Sleep Schedule', 'night_waking', 'Waking Up in the Night', 'A steady body clock makes sleep deeper and less likely to break in the night.', 'Go to bed and get up at about the same time every day, including weekends.', 'Daily.', 'Log bedtime, wake time and night wakings for 2 weeks.', 'Consistent sleep timing is a core part of good sleep habits.', NULL, false),
('no_clock_watching_night_waking', 'Stop Clock Watching and Reset Calmly', 'night_waking', 'Waking Up in the Night', 'Checking the time and worrying about sleep raises alertness and makes it harder to drift off.', 'Turn your clock away. If you are awake for roughly 20 minutes, get up, dim the lights and do something calm until sleepy.', 'Whenever you wake at night.', 'Note how long it takes to fall back asleep.', 'Getting out of bed when awake is a standard behavioural sleep technique.', NULL, true),
('evening_habits_night_waking', 'Ease Off Late Caffeine, Alcohol and Heavy Meals', 'night_waking', 'Waking Up in the Night', 'These can fragment sleep and cause waking in the second half of the night.', 'Skip caffeine after early afternoon, avoid alcohol close to bed, and finish large meals a few hours before sleep.', 'Evenings.', 'Compare nights after changing habits.', 'Caffeine, alcohol and late meals are well documented sleep disruptors.', 'Frequent waking with loud snoring, gasping or heavy daytime tiredness should be checked by a doctor.', true),
('wind_down_nightmares', 'Calming Wind-Down Routine', 'nightmares', 'Nightmares and Bad Dreams', 'A calmer mind going into sleep lowers the chance of distressing dreams.', 'For the last 30-60 minutes before bed, dim lights, put screens away and do something soothing like reading or gentle stretching.', 'Every evening.', 'Log how often nightmares happen over 2 weeks.', 'Relaxing pre-sleep routines are commonly recommended for better sleep.', NULL, false),
('rewrite_dream_nightmares', 'Write It Down and Rewrite the Ending', 'nightmares', 'Nightmares and Bad Dreams', 'Giving a bad dream a calmer ending in your imagination reduces its hold.', 'After a nightmare, jot it down, then write a new ending you prefer and read it through a few times during the day.', 'After a nightmare, then daily for a week or two.', 'Note whether the dream returns or feels less intense.', 'Imagery rehearsal is a recognised technique for recurring nightmares.', NULL, true),
('avoid_triggers_nightmares', 'Avoid Late Heavy Meals, Alcohol and Disturbing Content', 'nightmares', 'Nightmares and Bad Dreams', 'These can make sleep lighter and dreams more vivid and unsettling.', 'Keep late meals light, skip alcohol close to bed, and avoid scary or upsetting shows and news in the evening.', 'Evenings.', 'Compare nightmare frequency after changing habits.', 'Evening habits are known to influence dream intensity.', 'Frequent distressing nightmares for weeks, or nightmares tied to a frightening event, are worth talking to a doctor or counsellor about.', true),
('kind_self_talk_self_esteem', 'Talk to Yourself the Way You Would to a Friend', 'low_self_esteem', 'Low Self-Esteem / Body Image Worries', 'Harsh inner criticism feeds low self-worth, and a kinder voice gradually changes how you feel.', 'When a harsh thought shows up, pause and rewrite it into what you would say to a friend in the same situation.', 'Whenever it shows up.', 'Note how often harsh thoughts show up each week.', 'Self-compassion practices are linked to better self-esteem and wellbeing.', NULL, false),
('three_good_things_self_esteem', 'Write Down Three Things You Did Well', 'low_self_esteem', 'Low Self-Esteem / Body Image Worries', 'Noticing what went right counters the habit of focusing on flaws.', 'At the end of each day, write three things you did well or handled, however small.', 'Every evening.', 'Re-read your list weekly.', 'Keeping a daily record of wins is a common evidence-based confidence builder.', NULL, true),
('curate_feed_self_esteem', 'Curate What You Scroll', 'low_self_esteem', 'Low Self-Esteem / Body Image Worries', 'Constant comparison with filtered images and highlight reels can quietly chip away at self-worth.', 'Unfollow or mute accounts that leave you feeling worse, and follow some that feel realistic or uplifting.', 'One-time cleanup, then ongoing.', 'Notice your mood after scrolling for a week.', 'Reducing social comparison is linked to better body image and mood.', 'If low feelings are constant, or come with hopelessness, please talk to a doctor or counsellor.', true),
('slow_breathing_exam_nerves', 'Slow Breathing Before You Start', 'exam_nerves', 'Exam / Performance Nerves', 'Slow breathing calms the body''s stress response and steadies your nerves.', 'Breathe in through your nose for 4 counts and out slowly for 6, for 2-3 minutes before you begin.', 'Before the exam, interview or presentation.', 'Rate your nerves from 1-10 before and after.', 'Slow breathing is a well-supported way to reduce acute stress.', NULL, false),
('short_sessions_exam_nerves', 'Prepare in Short Sessions and Sleep Well', 'exam_nerves', 'Exam / Performance Nerves', 'Steady preparation and rest boost confidence and recall more than last-minute cramming.', 'Split revision or practice into short focused sessions, and aim for a proper night of sleep beforehand.', 'The days leading up to it.', 'Note how confident you feel as the date nears.', 'Spaced practice and adequate sleep both improve performance and reduce anxiety.', NULL, true),
('reframe_nerves_exam_nerves', 'Reframe Nerves as Energy', 'exam_nerves', 'Exam / Performance Nerves', 'A racing heart and butterflies are the same signs as excitement, and treating them that way helps performance.', 'Tell yourself ''I am fired up and ready'' instead of ''I am panicking'' when you notice nervous feelings.', 'Right before and during.', 'Notice whether nerves feel more manageable.', 'Reappraising anxiety as excitement has been shown to improve performance under pressure.', 'Panic attacks, or fear so strong you avoid attending, are worth talking to a doctor or counsellor about.', true),
('keep_dry_chafing', 'Keep the Area Clean and Dry', 'chafing', 'Chafing', 'Friction on damp skin is what causes chafing, so reducing moisture helps most.', 'Wash gently, pat the area completely dry and let it air out when you can.', 'Daily and after sweating.', 'Track redness and soreness each day.', 'Keeping skin dry is a core step in preventing and healing chafing.', NULL, false),
('barrier_chafing', 'Use a Barrier', 'chafing', 'Chafing', 'A slippery layer reduces friction where skin rubs together.', 'Apply petroleum jelly or an anti-chafe balm to rub-prone areas, or wear fitted shorts under skirts and dresses.', 'Before activity or long days in warm weather.', 'Note whether chafing improves.', 'Lubricating barriers are the standard prevention for friction chafing.', NULL, true),
('breathable_fabrics_chafing', 'Choose Smooth, Breathable Fabrics', 'chafing', 'Chafing', 'Rough seams and sweaty synthetic fabrics make friction worse.', 'Wear soft, breathable fabrics with flat seams, and change out of sweaty clothes quickly.', 'Ongoing.', 'Compare flare-ups across different clothes.', 'Clothing choice is a well-known factor in chafing.', 'Broken, weeping or very painful skin, or signs of infection, need a doctor.', true);
